private int readExtByte(ByteBuf buf, int codec, int... protocols) throws IOException {
    if (codec == CODEC_8 || codec == CODEC_8_EXT) {
        return buf.readUnsignedByte();
    } else if (Arrays.binarySearch(protocols, codec) >= 0) {
        return buf.readUnsignedShort();
    } else {
        throw new IOException("Unsupported protocol");
    }
}

