                    int flags = data.readUnsignedByte();
                    if (BitUtil.from(flags, 4) > 0) {
                        position.set("beacon" + index + "Uuid", ByteBufUtil.hexDump(data.readSlice(16)));
                        position.set("beacon" + index + "Major", data.readUnsignedShort());
